package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.util.Map;

/** Every person's figures on a sheet at one moment, keyed by person id in the order they were
 *  added, and the sheet's totals. A due-total is null when it is n/a. An overdue-total is the dues of
 *  the counting OPEN (or PENDING) claims whose due-by is before the sheet's today (n/a ones skipped). */
public record Snapshot(Map<Long, PersonFigures> people, BigDecimal claimedTotal, BigDecimal dueTotal, BigDecimal overdueTotal) {

    public record PersonFigures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
    }
}
package net.officefloor.hq.app.rollup;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.sheet.LeftDay;
import net.officefloor.plugin.variable.Val;

/** Runs as a new today takes effect: when the today moves, one SNAPSHOT line per person, in list
 *  order, with their due-total as it stood on the day being left (n/a when it is n/a), each also kept
 *  on the person as a snapshot line. Kept once the new today is set, so the sheet as it stood before
 *  the move (see {@link net.officefloor.hq.app.sheet.AsOf}) does not have it. */
public class RecordSnapshot {
    public void record(@Val RollupBefore before, @Val LocalDate today, @Val LeftDay left, @Val Actor actor, People people,
            Audit audit) {
        LocalDate leaving = left.day();
        if (today.equals(leaving)) return;
        String prefix = " sheet=" + before.sheetId() + " by=" + actor.user();
        before.snapshot().people().forEach((id, was) -> {
            audit.record("SNAPSHOT" + prefix + " name=" + was.name()
                    + " due-total=" + (was.dueTotal() == null ? "n/a" : was.dueTotal().setScale(2).toPlainString()));
            people.addSnapshot(before.sheetId(), id, leaving, was.dueTotal());
        });
    }
}
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import type { Person } from '../people/usePeople';

/**
 * A person's snapshot lines: one per SNAPSHOT written for them when the sheet's today moved, oldest
 * first, each the day being left and their due-total then (n/a when it was n/a).
 */
function PersonSnapshots({ person }: { user: string; sheet: string; person: Person }) {
  return (
    <td>
      {person.snapshots.map((line, i) => (
        <div key={i} data-testid="person-snapshot-line">
          {line}
        </div>
      ))}
    </td>
  );
}

export const contributions = [
  PersonColumns.fill({ order: 36, Component: () => <th>Snapshots</th> }),
  PersonCells.fill({ order: 36, Component: PersonSnapshots }),
];
# Change the sheet's today. Validate first so a bad date is a 400 and writes nothing.
validate:
  class: net.officefloor.hq.app.sheet.ValidateToday
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.sheet.ApplyToday
  govern: [ transaction ]
  next: record-snapshot
# A changed today writes each person's due-total on the day being left (as kept before the change),
# once the new today is set: the sheet as it stood before the move has none.
record-snapshot:
  class: net.officefloor.hq.app.rollup.RecordSnapshot
  govern: [ transaction ]
  next: autoclose
# Once the new today is set, close the periods past their grace days, before the rollup lines.
autoclose:
  class: net.officefloor.hq.app.period.AutoClosePeriods
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
  govern: [ transaction ]

